1	/**
2	 * Execution State Management for CLI Interactive Mode
3	 *
4	 * Provides persistent state for turn-by-turn execution across separate CLI calls.
5	 * Each execution is stored in .dygram/executions/<id>/ with state, metadata, and history.
6	 */
7	
8	import * as fs from 'node:fs/promises';
9	import * as path from 'node:path';
10	import * as crypto from 'node:crypto';
11	import type { MachineJSON } from '../language/json/types.js';
12	import type { TurnState } from '../language/execution/turn-types.js';
13	
14	/**
15	 * Execution state file format
16	 */
17	export interface ExecutionStateFile {
18	    version: string;                      // State format version
19	    machineHash: string;                  // Hash of machine definition
20	    executionState: {                     // From executor.getExecutionState()
21	        currentNode: string;
22	        pathId: string;
23	        visitedNodes: string[];
24	        attributes: Record<string, any>;
25	        contextValues: Record<string, any>;
26	        turnState?: TurnState;            // If in mid-turn
27	        paths?: any[];                    // Full paths array (for multi-path execution)
28	        barriers?: Record<string, any>;   // Barrier synchronization state
29	    };
30	    status: 'in_progress' | 'complete' | 'error' | 'paused';
31	    lastUpdated: string;                  // ISO timestamp
32	}
33	
34	/**
35	 * Execution metadata
36	 */
37	export interface ExecutionMetadata {
38	    id: string;                           // Execution ID
39	    machineFile?: string;                 // Original machine file path (if from file)
40	    machineSource: 'file' | 'stdin';      // Source type
41	    startedAt: string;                    // ISO timestamp
42	    lastExecutedAt: string;               // ISO timestamp
43	    turnCount: number;                    // Total turns executed
44	    stepCount: number;                    // Total steps executed
45	    status: 'in_progress' | 'complete' | 'error' | 'paused';
46	    mode: 'interactive' | 'playback' | 'auto';
47	    nextPathId?: string;                  // For --step-path mode: next path to step (round-robin)
48	    clientConfig?: {                      // Client configuration
49	        type: 'playback' | 'interactive' | 'api';
50	        recordingsDir?: string;
51	        playbackDir?: string;
52	    };
53	}
54	
55	/**
56	 * Turn history entry (JSONL format)
57	 */
58	export interface TurnHistoryEntry {
59	    turn: number;
60	    timestamp: string;
61	    node: string;
62	    tools: string[];
63	    output?: string;
64	    status: string;
65	}
66	
67	/**
68	 * Options for loading or creating execution
69	 */
70	export interface LoadExecutionOptions {
71	    machineSource?: string;      // File path or machine DSL source (optional when resuming with executionId)
72	    isStdin?: boolean;           // True if source is stdin (not file)
73	    executionId?: string;        // Explicit ID, or undefined for "last"
74	    playback?: string;           // Playback directory
75	    record?: string;             // Recording directory
76	    force?: boolean;             // Force new execution even if state exists
77	    isInteractive?: boolean;     // Interactive mode with stdin/stdout
78	    input?: any;                 // Input data for this turn (LLM response)
79	}
80	
81	/**
82	 * State directory configuration
83	 */
84	export const STATE_CONFIG = {
85	    baseDir: '.dygram',
86	    executionsDir: 'executions',
87	    lastSymlink: 'last',
88	    stateFileName: 'state.json',
89	    metadataFileName: 'metadata.json',
90	    machineFileName: 'machine.json',
91	    historyFileName: 'history.jsonl',
92	    stateVersion: '1.0'
93	};
94	
95	/**
96	 * Get the base state directory path
97	 */
98	export function getStateBaseDir(): string {
99	    return path.join(process.cwd(), STATE_CONFIG.baseDir, STATE_CONFIG.executionsDir);
100	}
101	
102	/**
103	 * Get execution directory path
104	 */
105	export function getExecutionDir(executionId: string): string {
106	    return path.join(getStateBaseDir(), executionId);
107	}
108	
109	/**
110	 * Generate a unique execution ID
111	 */
112	export function generateExecutionId(): string {
113	    const timestamp = new Date().toISOString()
114	        .replace(/[-:]/g, '')
115	        .replace(/\.\d+Z$/, '')
116	        .replace('T', '-');
117	    return `exec-${timestamp}`;
118	}
119	
120	/**
121	 * Generate hash of machine definition for validation
122	 */
123	export function hashMachine(machineData: MachineJSON): string {
124	    const json = JSON.stringify(machineData, Object.keys(machineData).sort());
125	    return crypto.createHash('sha256').update(json).digest('hex');
126	}
127	
128	/**
129	 * Get the "last" execution ID from symlink
130	 */
131	export async function getLastExecutionId(): Promise<string | null> {
132	    const baseDir = getStateBaseDir();
133	    const lastLink = path.join(baseDir, STATE_CONFIG.lastSymlink);
134	
135	    try {
136	        const stats = await fs.lstat(lastLink);
137	        if (stats.isSymbolicLink()) {
138	            const target = await fs.readlink(lastLink);
139	            return path.basename(target);
140	        }
141	    } catch (error) {
142	        // Symlink doesn't exist
143	    }
144	
145	    return null;
146	}
147	
148	/**
149	 * Update the "last" symlink to point to an execution
150	 */
151	export async function updateLastSymlink(executionId: string): Promise<void> {
152	    const baseDir = getStateBaseDir();
153	    const lastLink = path.join(baseDir, STATE_CONFIG.lastSymlink);
154	
155	    // Remove existing symlink
156	    try {
157	        await fs.unlink(lastLink);
158	    } catch {
159	        // Doesn't exist, that's fine
160	    }
161	
162	    // Create new symlink
163	    await fs.symlink(executionId, lastLink);
164	}
165	
166	/**
167	 * Check if execution exists
168	 */
169	export async function executionExists(executionId: string): Promise<boolean> {
170	    const execDir = getExecutionDir(executionId);
171	    const stateFile = path.join(execDir, STATE_CONFIG.stateFileName);
172	
173	    try {
174	        await fs.access(stateFile);
175	        return true;
176	    } catch {
177	        return false;
178	    }
179	}
180	
181	/**
182	 * Load execution state from file
183	 */
184	export async function loadExecutionState(executionId: string): Promise<ExecutionStateFile> {
185	    const execDir = getExecutionDir(executionId);
186	    const stateFile = path.join(execDir, STATE_CONFIG.stateFileName);
187	
188	    const content = await fs.readFile(stateFile, 'utf-8');
189	    return JSON.parse(content);
190	}
191	
192	/**
193	 * Save execution state to file
194	 */
195	export async function saveExecutionState(
196	    executionId: string,
197	    state: ExecutionStateFile
198	): Promise<void> {
199	    const execDir = getExecutionDir(executionId);
200	    const stateFile = path.join(execDir, STATE_CONFIG.stateFileName);
201	
202	    await fs.mkdir(execDir, { recursive: true });
203	    await fs.writeFile(stateFile, JSON.stringify(state, null, 2));
204	}
205	
206	/**
207	 * Load execution metadata from file
208	 */
209	export async function loadExecutionMetadata(executionId: string): Promise<ExecutionMetadata> {
210	    const execDir = getExecutionDir(executionId);
211	    const metadataFile = path.join(execDir, STATE_CONFIG.metadataFileName);
212	
213	    const content = await fs.readFile(metadataFile, 'utf-8');
214	    return JSON.parse(content);
215	}
216	
217	/**
218	 * Save execution metadata to file
219	 */
220	export async function saveExecutionMetadata(
221	    executionId: string,
222	    metadata: ExecutionMetadata
223	): Promise<void> {
224	    const execDir = getExecutionDir(executionId);
225	    const metadataFile = path.join(execDir, STATE_CONFIG.metadataFileName);
226	
227	    await fs.mkdir(execDir, { recursive: true });
228	    await fs.writeFile(metadataFile, JSON.stringify(metadata, null, 2));
229	}
230	
231	/**
232	 * Save machine snapshot to file
233	 */
234	export async function saveMachineSnapshot(
235	    executionId: string,
236	    machineData: MachineJSON
237	): Promise<void> {
238	    const execDir = getExecutionDir(executionId);
239	    const machineFile = path.join(execDir, STATE_CONFIG.machineFileName);
240	
241	    await fs.mkdir(execDir, { recursive: true });
242	    await fs.writeFile(machineFile, JSON.stringify(machineData, null, 2));
243	}
244	
245	/**
246	 * Load machine snapshot from file
247	 */
248	export async function loadMachineSnapshot(executionId: string): Promise<MachineJSON> {
249	    const execDir = getExecutionDir(executionId);
250	    const machineFile = path.join(execDir, STATE_CONFIG.machineFileName);
251	
252	    const content = await fs.readFile(machineFile, 'utf-8');
253	    return JSON.parse(content);
254	}
255	
256	/**
257	 * Append entry to turn history (JSONL format)
258	 */
259	export async function appendTurnHistory(
260	    executionId: string,
261	    entry: TurnHistoryEntry
262	): Promise<void> {
263	    const execDir = getExecutionDir(executionId);
264	    const historyFile = path.join(execDir, STATE_CONFIG.historyFileName);
265	
266	    await fs.mkdir(execDir, { recursive: true });
267	    await fs.appendFile(historyFile, JSON.stringify(entry) + '\n');
268	}
269	
270	/**
271	 * Load turn history
272	 */
273	export async function loadTurnHistory(executionId: string): Promise<TurnHistoryEntry[]> {
274	    const execDir = getExecutionDir(executionId);
275	    const historyFile = path.join(execDir, STATE_CONFIG.historyFileName);
276	
277	    try {
278	        const content = await fs.readFile(historyFile, 'utf-8');
279	        return content
280	            .trim()
281	            .split('\n')
282	            .filter(line => line.length > 0)
283	            .map(line => JSON.parse(line));
284	    } catch {
285	        return [];
286	    }
287	}
288	
289	/**
290	 * List all executions
291	 */
292	export async function listExecutions(): Promise<ExecutionMetadata[]> {
293	    const baseDir = getStateBaseDir();
294	
295	    try {
296	        const entries = await fs.readdir(baseDir);
297	        const executions: ExecutionMetadata[] = [];
298	
299	        for (const entry of entries) {
300	            if (entry === STATE_CONFIG.lastSymlink) continue;
301	
302	            try {
303	                const metadata = await loadExecutionMetadata(entry);
304	                executions.push(metadata);
305	            } catch {
306	                // Skip invalid executions
307	            }
308	        }
309	
310	        // Sort by last executed time (most recent first)
311	        executions.sort((a, b) =>
312	            new Date(b.lastExecutedAt).getTime() - new Date(a.lastExecutedAt).getTime()
313	        );
314	
315	        return executions;
316	    } catch {
317	        return [];
318	    }
319	}
320	
321	/**
322	 * Remove execution
323	 */
324	export async function removeExecution(executionId: string): Promise<void> {
325	    const execDir = getExecutionDir(executionId);
326	
327	    // Check if this is the "last" execution
328	    const lastId = await getLastExecutionId();
329	    if (lastId === executionId) {
330	        // Remove last symlink
331	        const baseDir = getStateBaseDir();
332	        const lastLink = path.join(baseDir, STATE_CONFIG.lastSymlink);
333	        try {
334	            await fs.unlink(lastLink);
335	        } catch {
336	            // Already removed
337	        }
338	    }
339	
340	    // Remove execution directory
341	    await fs.rm(execDir, { recursive: true, force: true });
342	}
343	
344	/**
345	 * Result of cleaning executions
346	 */
347	export interface CleanExecutionsResult {
348	    cleaned: number;    // Successfully removed
349	    pending: number;    // In progress or paused (not cleaned when --all not provided)
350	    error: number;      // With error status (not cleaned when --all not provided)
351	    failed: number;     // Failed to remove
352	}
353	
354	/**
355	 * Clean completed executions
356	 */
357	export async function cleanCompletedExecutions(options: { all?: boolean } = {}): Promise<CleanExecutionsResult> {
358	    const executions = await listExecutions();
359	    const result: CleanExecutionsResult = {
360	        cleaned: 0,
361	        pending: 0,
362	        error: 0,
363	        failed: 0
364	    };
365	
366	    for (const execution of executions) {
367	        if (options.all || execution.status === 'complete') {
368	            try {
369	                await removeExecution(execution.id);
370	                result.cleaned++;
371	            } catch {
372	                // Failed to remove
373	                result.failed++;
374	            }
375	        } else {
376	            // Not cleaned - categorize by status
377	            if (execution.status === 'error') {
378	                result.error++;
379	            } else {
380	                // in_progress or paused
381	                result.pending++;
382	            }
383	        }
384	    }
385	
386	    return result;
387	}
