1	/**
2	 * Interactive Execution Orchestration for CLI
3	 *
4	 * Handles turn-by-turn execution with persistent state across CLI calls.
5	 */
6	
7	import chalk from 'chalk';
8	import * as path from 'node:path';
9	import * as fs from 'node:fs/promises';
10	import * as os from 'node:os';
11	import { MachineExecutor } from '../language/executor.js';
12	import type { MachineJSON } from '../language/json/types.js';
13	import type { Machine } from '../language/generated/ast.js';
14	import { createMachineServices } from '../language/machine-module.js';
15	import { extractAstNode } from './cli-util.js';
16	import { NodeFileSystem } from 'langium/node';
17	import { generateJSON } from '../language/generator/generator.js';
18	import { PlaybackTestClient } from '../language/playback-test-client.js';
19	import { InteractiveTestClient } from '../language/interactive-test-client.js';
20	import { StdinResponseClient, PendingResponseError } from '../language/stdin-response-client.js';
21	import { logger } from './logger.js';
22	import { RuntimeVisualizer, formatRuntimeSnapshot, formatRuntimeSnapshotJSON, formatRuntimeSnapshotCompact } from '../language/runtime-visualizer.js';
23	
24	// Re-export visualization utilities
25	export { RuntimeVisualizer, formatRuntimeSnapshot, formatRuntimeSnapshotJSON, formatRuntimeSnapshotCompact };
26	import {
27	    type LoadExecutionOptions,
28	    type ExecutionMetadata,
29	    type ExecutionStateFile,
30	    type TurnHistoryEntry,
31	    generateExecutionId,
32	    hashMachine,
33	    getLastExecutionId,
34	    updateLastSymlink,
35	    executionExists,
36	    loadExecutionState,
37	    saveExecutionState,
38	    loadExecutionMetadata,
39	    saveExecutionMetadata,
40	    saveMachineSnapshot,
41	    loadMachineSnapshot,
42	    appendTurnHistory,
43	    STATE_CONFIG
44	} from './execution-state.js';
45	
46	/**
47	 * Result of loading or creating an execution
48	 */
49	export interface LoadedExecution {
50	    executor: MachineExecutor;
51	    metadata: ExecutionMetadata;
52	    isNew: boolean;
53	}
54	
55	/**
56	 * Parse machine from DSL source string
57	 */
58	async function parseMachineFromSource(source: string): Promise<MachineJSON> {
59	    // Write source to temp file
60	    const tempFile = path.join(os.tmpdir(), `dygram-stdin-${Date.now()}.dy`);
61	    await fs.writeFile(tempFile, source);
62	
63	    try {
64	        // Parse using existing infrastructure
65	        const services = createMachineServices(NodeFileSystem).Machine;
66	        const model = await extractAstNode<Machine>(tempFile, services);
67	        const jsonContent = generateJSON(model, tempFile);
68	        return JSON.parse(jsonContent.content) as MachineJSON;
69	    } finally {
70	        // Clean up temp file
71	        await fs.unlink(tempFile).catch(() => {});
72	    }
73	}
74	
75	/**
76	 * Load machine from file
77	 */
78	async function loadMachineFromFile(filePath: string): Promise<MachineJSON> {
79	    const services = createMachineServices(NodeFileSystem).Machine;
80	    const model = await extractAstNode<Machine>(filePath, services);
81	    const jsonContent = generateJSON(model, filePath);
82	    return JSON.parse(jsonContent.content) as MachineJSON;
83	}
84	
85	/**
86	 * Configure LLM client based on options
87	 */
88	function configureClient(opts: LoadExecutionOptions): any {
89	    // Interactive mode with stdin/stdout (with or without recording)
90	    if (opts.isInteractive && !opts.playback) {
91	        return {
92	            llm: new StdinResponseClient({
93	                modelId: 'cli-interactive',
94	                responseInput: opts.input ? JSON.stringify(opts.input) : undefined,
95	                recordingsDir: opts.record  // Enable recording if --record is set
96	            })
97	        };
98	    }
99	
100	    if (opts.playback) {
101	        return {
102	            llm: new PlaybackTestClient({
103	                recordingsDir: opts.playback,
104	                simulateDelay: true,
105	                delay: 100,
106	                strict: true,
107	                matchingMode: 'hybrid'
108	            })
109	        };
110	    }
111	
112	    // Default: use API client
113	    const modelId = process.env.ANTHROPIC_MODEL_ID || 'claude-3-5-haiku-20241022';
114	    return {
115	        llm: {
116	            provider: 'anthropic' as const,
117	            apiKey: process.env.ANTHROPIC_API_KEY,
118	            modelId
119	        },
120	        agentSDK: {
121	            model: 'sonnet' as const,
122	            modelId,
123	            apiKey: process.env.ANTHROPIC_API_KEY,
124	            maxTurns: 50,
125	            persistHistory: true
126	        }
127	    };
128	}
129	
130	/**
131	 * Load or create execution
132	 */
133	export async function loadOrCreateExecution(
134	    opts: LoadExecutionOptions
135	): Promise<LoadedExecution> {
136	    // Resolve execution ID
137	    let executionId = opts.executionId;
138	    let isNew = false;
139	
140	    if (!executionId && !opts.force) {
141	        // Try to use "last" execution
142	        const lastId = await getLastExecutionId();
143	        if (lastId) {
144	            executionId = lastId;
145	            logger.info(chalk.blue(`⚡ Resuming execution: ${executionId}`));
146	        }
147	    }
148	
149	    if (!executionId || opts.force) {
150	        // Create new execution
151	        executionId = opts.executionId || generateExecutionId();
152	        isNew = true;
153	        logger.info(chalk.blue(`⚡ Starting interactive execution: ${executionId}`));
154	    }
155	
156	    let executor: MachineExecutor;
157	    let metadata: ExecutionMetadata;
158	    let machineData: MachineJSON;
159	
160	    if (isNew || !(await executionExists(executionId))) {
161	        // Create new execution
162	        logger.debug('Creating new execution');
163	
164	        // Validate machine source is provided for new execution
165	        if (!opts.machineSource) {
166	            throw new Error('Machine source required when creating new execution');
167	        }
168	
169	        // Load or create machine from source
170	        if (opts.isStdin) {
171	            // Parse machine from stdin source
172	            machineData = await parseMachineFromSource(opts.machineSource);
173	        } else {
174	            // Load machine from file
175	            machineData = await loadMachineFromFile(opts.machineSource);
176	        }
177	
178	        // Configure client
179	        const clientConfig = configureClient(opts);
180	
181	        // Show mode info
182	        if (opts.playback) {
183	            logger.info(chalk.gray(`   Mode: playback (${opts.playback})`));
184	        } else if (opts.record) {
185	            logger.info(chalk.gray(`   Mode: interactive (recording to ${opts.record})`));
186	        }
187	
188	        // Create executor
189	        executor = await MachineExecutor.create(machineData, clientConfig);
190	
191	        // Create metadata
192	        metadata = {
193	            id: executionId,
194	            machineFile: opts.isStdin ? undefined : opts.machineSource,
195	            machineSource: opts.isStdin ? 'stdin' : 'file',
196	            startedAt: new Date().toISOString(),
197	            lastExecutedAt: new Date().toISOString(),
198	            turnCount: 0,
199	            stepCount: 0,
200	            status: 'in_progress',
201	            mode: opts.playback ? 'playback' : 'interactive',
202	            clientConfig: {
203	                type: opts.playback ? 'playback' : opts.record ? 'interactive' : 'api',
204	                playbackDir: opts.playback,
205	                recordingsDir: opts.record
206	            }
207	        };
208	
209	        await saveExecutionMetadata(executionId, metadata);
210	        await saveMachineSnapshot(executionId, machineData);
211	
212	        // Update "last" symlink
213	        await updateLastSymlink(executionId);
214	
215	    } else {
216	        // Resume existing execution - load from snapshot (not source file)
217	        logger.debug('Resuming existing execution');
218	
219	        const state: ExecutionStateFile = await loadExecutionState(executionId);
220	        metadata = await loadExecutionMetadata(executionId);
221	
222	        // Load machine from snapshot (which may have been modified by meta-tools)
223	        machineData = await loadMachineSnapshot(executionId);
224	
225	        // Show mode info
226	        if (metadata.mode === 'playback') {
227	            logger.info(chalk.gray(`   Mode: playback (${metadata.clientConfig?.playbackDir})`));
228	        } else if (metadata.clientConfig?.recordingsDir) {
229	            logger.info(chalk.gray(`   Mode: interactive (recording to ${metadata.clientConfig.recordingsDir})`));
230	        }
231	
232	        // Recreate client with same config
233	        const clientConfig = configureClient({
234	            ...opts,
235	            playback: metadata.clientConfig?.playbackDir,
236	            record: metadata.clientConfig?.recordingsDir
237	        });
238	
239	        // Recreate executor with snapshot machine
240	        executor = await MachineExecutor.create(machineData, clientConfig);
241	
242	        // Restore execution state
243	        const currentExecState = executor.getState();
244	        const restoredState = {
245	            ...currentExecState,
246	            contextState: state.executionState.contextValues,
247	            turnState: state.executionState.turnState,
248	            // Restore full paths array if available, otherwise use legacy single-path restore
249	            paths: state.executionState.paths || currentExecState.paths.map((path, index) => {
250	                if (index === 0) {
251	                    // Legacy restore: only restore the first path
252	                    return {
253	                        ...path,
254	                        currentNode: state.executionState.currentNode,
255	                        // Note: We keep the newly initialized history as the executor
256	                        // will properly reconstruct it during execution
257	                    };
258	                }
259	                return path;
260	            }),
261	            // Restore barrier state
262	            barriers: state.executionState.barriers || {}
263	        };
264	        executor.setState(restoredState);
265	
266	        logger.debug(chalk.gray(`   State restored: ${state.executionState.currentNode}`));
267	    }
268	
269	    return { executor, metadata, isNew };
270	}
271	
272	/**
273	 * Get execution status from state
274	 */
275	function getExecutionStatus(state: any): 'in_progress' | 'complete' | 'error' | 'paused' {
276	    if (!state.paths || state.paths.length === 0) {
277	        // No active paths means execution is complete
278	        return 'complete';
279	    }
280	
281	    const activePath = state.paths[0];
282	    // Check for 'completed' (with 'd') which is the actual PathStatus value
283	    if (activePath.status === 'completed') return 'complete';
284	    if (activePath.status === 'failed') return 'error';
285	    if (state.turnState) return 'paused';
286	    return 'in_progress';
287	}
288	
289	/**
290	 * Save current execution state
291	 */
292	export async function saveCurrentExecutionState(
293	    executionId: string,
294	    executor: MachineExecutor,
295	    metadata: ExecutionMetadata
296	): Promise<void> {
297	    // Get current state from executor
298	    const execState = executor.getState();
299	    const machineData = executor.getMachineDefinition();
300	    
301	    logger.debug(`Saving machine with ${machineData.nodes.length} nodes: ${machineData.nodes.map(n => n.name).join(', ')}`);
302	
303	    // Get the active path (first path)
304	    const activePath = execState.paths[0];
305	
306	    // Create state file with updated machine hash
307	    const updatedMachineHash = hashMachine(machineData);
308	    const state: ExecutionStateFile = {
309	        version: STATE_CONFIG.stateVersion,
310	        machineHash: updatedMachineHash,  // Updated hash to reflect machine modifications
311	        executionState: {
312	            currentNode: activePath?.currentNode || '',
313	            pathId: activePath?.id || '',
314	            visitedNodes: activePath ? Array.from(new Set([
315	                ...activePath.history.map(t => t.from),
316	                ...activePath.history.map(t => t.to),
317	                activePath.currentNode
318	            ])) : [],
319	            attributes: {},
320	            contextValues: execState.contextState || {},
321	            turnState: execState.turnState,
322	            paths: execState.paths,           // Save full paths array
323	            barriers: execState.barriers       // Save barrier state
324	        },
325	        status: getExecutionStatus(execState),
326	        lastUpdated: new Date().toISOString()
327	    };
328	
329	    await saveExecutionState(executionId, state);
330	
331	    // Save machine snapshot (in case it was modified by meta-tools)
332	    await saveMachineSnapshot(executionId, machineData);
333	
334	    // Update metadata
335	    metadata.lastExecutedAt = new Date().toISOString();
336	    metadata.status = state.status;
337	    metadata.stepCount = activePath?.stepCount || 0;
338	    if (executor.isInTurn()) {
339	        metadata.turnCount = executor.getTurnState()?.turnCount || metadata.turnCount;
340	    }
341	
342	    await saveExecutionMetadata(executionId, metadata);
343	
344	    logger.success(chalk.gray('💾 State saved'));
345	}
