437	/**
438	 * Execute machine with specified execution mode
439	 * - No flags: Run to completion
440	 * - --interactive: Run until LLM needed or completion
441	 * - --step: Execute one step, pause
442	 * - --step-turn: Execute one turn, pause
443	 * - --interactive --step: Execute one step, pause on LLM or after step
444	 * - --interactive --step-turn: Execute one turn, pause on LLM or after turn
445	 */
446	export async function executeInteractiveTurn(
447	    machineSource: string,
448	    opts: {
449	        id?: string;
450	        playback?: string;
451	        record?: string;
452	        force?: boolean;
453	        verbose?: boolean;
454	        input?: any;
455	        isStdin?: boolean;
456	        interactive?: boolean;
457	        step?: boolean;
458	        stepTurn?: boolean;
459	        stepPath?: boolean;
460	        format?: string;
461	    }
462	): Promise<void> {
463	    // Load or create execution
464	    const { executor, metadata } = await loadOrCreateExecution({
465	        machineSource,
466	        executionId: opts.id,
467	        playback: opts.playback,
468	        record: opts.record,
469	        force: opts.force,
470	        isStdin: opts.isStdin,
471	        isInteractive: opts.interactive,
472	        input: opts.input
473	    });
474	
475	    const executionId = metadata.id;
476	
477	    // Check if already complete
478	    const state = executor.getState();
479	    const status = getExecutionStatus(state);
480	    if (status === 'complete') {
481	        logger.success(chalk.green('✅ Execution already complete!'));
482	        displayFinalResults(executor, metadata);
483	        return;
484	    }
485	
486	    // Determine execution mode
487	    const isStepMode = opts.step || opts.stepTurn || opts.stepPath;
488	    const shouldLoop = !isStepMode; // Loop if not in step mode
489	
490	    // Show mode info
491	    if (opts.step) {
492	        logger.info(chalk.gray('🔍 Step mode: executing one step at a time (all paths)'));
493	    } else if (opts.stepTurn) {
494	        logger.info(chalk.gray('🔍 Step-turn mode: executing one turn at a time'));
495	    } else if (opts.stepPath) {
496	        logger.info(chalk.gray('🔍 Step-path mode: executing one path at a time'));
497	    } else if (opts.interactive) {
498	        logger.info(chalk.gray('🔄 Interactive mode: running until LLM response needed'));
499	    }
500	
501	    // For step-path mode, track which path to step next
502	    let currentPathId: string | undefined;
503	    if (opts.stepPath && !metadata.nextPathId) {
504	        // Initialize with first active path
505	        currentPathId = executor.getNextActivePathId();
506	        metadata.nextPathId = currentPathId;
507	    } else if (opts.stepPath) {
508	        // Resume from saved path
509	        currentPathId = metadata.nextPathId;
510	    }
511	
512	    // Execute loop
513	    let iterationCount = 0;
514	    const maxIterations = shouldLoop ? 1000 : 1; // Safety limit for loop mode
515	
516	    while (iterationCount < maxIterations) {
517	        iterationCount++;
518	
519	        try {
520	            let result: any;
521	
522	            // Execute based on mode
523	            if (opts.stepPath) {
524	                // Step-path mode: execute one path at a time
525	                if (!currentPathId) {
526	                    logger.error('No active paths to step');
527	                    return;
528	                }
529	
530	                const currentState = executor.getState();
531	                const pathToStep = currentState.paths.find(p => p.id === currentPathId);
532	
533	                if (!pathToStep) {
534	                    logger.error(`Path ${currentPathId} not found`);
535	                    return;
536	                }
537	
538	                logger.info(chalk.cyan(`\n📍 Step ${metadata.stepCount + 1} - Path: ${currentPathId} - Node: ${pathToStep.currentNode}`));
539	
540	                const hasMore = await executor.stepPath(currentPathId);
541	                result = {
542	                    status: hasMore ? 'in_progress' : 'complete',
543	                    stepCount: metadata.stepCount + 1
544	                };
545	                metadata.stepCount++;
546	
547	                // Move to next path (round-robin)
548	                currentPathId = executor.getNextActivePathId(currentPathId);
549	                metadata.nextPathId = currentPathId;
550	
551	            } else if (opts.step) {
552	                // Step mode: execute one step (all paths)
553	                const currentState = executor.getState();
554	                const currentNode = currentState.paths[0]?.currentNode || '';
555	                logger.info(chalk.cyan(`\n📍 Step ${metadata.stepCount + 1} - Node: ${currentNode}`));
556	
557	                const hasMore = await executor.step();
558	                result = {
559	                    status: hasMore ? 'in_progress' : 'complete',
560	                    stepCount: metadata.stepCount + 1
561	                };
562	                metadata.stepCount++;
563	            } else {
564	                // Turn mode (default): execute one turn
565	                if (executor.isInTurn()) {
566	                    // Continue turn
567	                    const turnState = executor.getTurnState();
568	                    logger.info(chalk.cyan(`\n📍 Turn ${turnState!.turnCount} - Node: ${turnState!.nodeName}`));
569	                    result = await executor.stepTurn();
570	                } else {
571	                    // Start new turn
572	                    const currentState = executor.getState();
573	                    const currentNode = currentState.paths[0]?.currentNode || '';
574	                    logger.info(chalk.cyan(`\n📍 Current Node: ${currentNode}`));
575	                    result = await executor.stepTurn();
576	                }
577	
578	                // Display turn result
579	                displayTurnResult(result);
580	
581	                // Create history entry
582	                const updatedState = executor.getState();
583	                const historyEntry: TurnHistoryEntry = {
584	                    turn: result.turnCount || metadata.turnCount + 1,
585	                    timestamp: new Date().toISOString(),
586	                    node: result.nodeName || updatedState.paths[0]?.currentNode || '',
587	                    tools: result.toolExecutions?.map((t: any) => t.toolName) || [],
588	                    output: result.text?.slice(0, 100),
589	                    status: result.status
590	                };
591	
592	                // Append to history
593	                await appendTurnHistory(executionId, historyEntry);
594	
595	                // Increment turn count if turn completed
596	                if (result.status !== 'in_turn') {
597	                    metadata.turnCount++;
598	                }
599	            }
600	
601	            // Save state
602	            await saveCurrentExecutionState(executionId, executor, metadata);
603	
604	            // Display runtime snapshot
605	            displayRuntimeSnapshot(executor, { verbose: opts.verbose, format: opts.format });
606	
607	            // Check if complete
608	            const finalStatus = getExecutionStatus(executor.getState());
609	            if (finalStatus === 'complete') {
610	                logger.success(chalk.green('\n✅ Execution complete!'));
611	                displayFinalResults(executor, metadata);
612	                return;
613	            }
614	
615	            // Exit loop if in step mode (only execute once)
616	            if (isStepMode) {
617	                logger.info(chalk.gray(`\n💾 State saved. Run again to continue.`));
618	                return;
619	            }
620	
621	        } catch (error) {
622	            // Handle pending response (interactive mode)
623	            if (error instanceof PendingResponseError) {
624	                logger.info(chalk.yellow('\n⏸️  Waiting for LLM response...\n'));
625	                logger.output(chalk.dim('─'.repeat(60)));
626	                logger.output(chalk.bold('LLM REQUEST:'));
627	                logger.output(error.request);
628	                logger.output(chalk.dim('─'.repeat(60)));
629	                logger.output(chalk.bold('\nEXAMPLE RESPONSE:'));
630	                logger.output(error.exampleResponse);
631	                logger.output(chalk.dim('─'.repeat(60)));
632	                logger.info(chalk.cyan('\n💡 Provide response via stdin:'));
633	                logger.info(chalk.gray(`   echo '<response-json>' | dygram execute <machine> --interactive --id ${executionId}\n`));
634	
635	                // Save state as paused
636	                metadata.status = 'paused';
637	                await saveCurrentExecutionState(executionId, executor, metadata);
638	                return;
639	            }
640	
641	            // Other errors
642	            logger.error(chalk.red(`\n❌ Error: ${error instanceof Error ? error.message : String(error)}`));
643	
644	            // Save error state
645	            metadata.status = 'error';
646	            await saveCurrentExecutionState(executionId, executor, metadata);
647	
648	            throw error;
649	        }
650	    }
651	
652	    // Safety check: if we hit max iterations
653	    if (shouldLoop) {
654	        logger.warn(chalk.yellow(`\n⚠️  Reached maximum iterations (${maxIterations}). Execution paused.`));
655	        logger.info(chalk.gray(`   Run again to continue: dygram execute --interactive --id ${executionId}\n`));
656	    }
657	}
