1	/**
2	 * Virtual File System for Playground
3	 *
4	 * Provides an in-memory file system for the browser-based playground
5	 * with localStorage persistence.
6	 */
7	
8	export interface VirtualFile {
9	    path: string;
10	    content: string;
11	    lastModified: number;
12	}
13	
14	export class VirtualFileSystem {
15	    private files = new Map<string, VirtualFile>();
16	    private readonly storageKey: string;
17	
18	    constructor(storageKey: string = 'dygram-vfs') {
19	        this.storageKey = storageKey;
20	    }
21	
22	    /**
23	     * Read a file from the virtual filesystem
24	     */
25	    readFile(path: string): string | undefined {
26	        const file = this.files.get(this.normalizePath(path));
27	        return file?.content;
28	    }
29	
30	    /**
31	     * Write a file to the virtual filesystem
32	     */
33	    writeFile(path: string, content: string): void {
34	        const normalizedPath = this.normalizePath(path);
35	        this.files.set(normalizedPath, {
36	            path: normalizedPath,
37	            content,
38	            lastModified: Date.now()
39	        });
40	    }
41	
42	    /**
43	     * Delete a file from the virtual filesystem
44	     */
45	    deleteFile(path: string): boolean {
46	        return this.files.delete(this.normalizePath(path));
47	    }
48	
49	    /**
50	     * Check if a file exists
51	     */
52	    exists(path: string): boolean {
53	        return this.files.has(this.normalizePath(path));
54	    }
55	
56	    /**
57	     * List all files in a directory
58	     */
59	    listFiles(directory: string = '/'): string[] {
60	        const normalizedDir = this.normalizePath(directory);
61	        const dirWithSlash = normalizedDir.endsWith('/') ? normalizedDir : normalizedDir + '/';
62	
63	        const files: string[] = [];
64	
65	        for (const path of this.files.keys()) {
66	            if (directory === '/' || path.startsWith(dirWithSlash)) {
67	                const relativePath = directory === '/' ? path : path.slice(dirWithSlash.length);
68	                // Only include direct children (not nested in subdirectories)
69	                if (!relativePath.includes('/') || relativePath.endsWith('/')) {
70	                    files.push(path);
71	                }
72	            }
73	        }
74	
75	        return files.sort();
76	    }
77	
78	    /**
79	     * List all directories in a directory
80	     */
81	    listDirectories(directory: string = '/'): string[] {
82	        const normalizedDir = this.normalizePath(directory);
83	        const dirWithSlash = normalizedDir.endsWith('/') ? normalizedDir : normalizedDir + '/';
84	
85	        const directories = new Set<string>();
86	
87	        for (const path of this.files.keys()) {
88	            if (path.startsWith(dirWithSlash)) {
89	                const relativePath = path.slice(dirWithSlash.length);
90	                const slashIndex = relativePath.indexOf('/');
91	                if (slashIndex !== -1) {
92	                    const subdir = dirWithSlash + relativePath.slice(0, slashIndex);
93	                    directories.add(subdir);
94	                }
95	            }
96	        }
97	
98	        return Array.from(directories).sort();
99	    }
100	
101	    /**
102	     * Get all files in the filesystem
103	     */
104	    getAllFiles(): VirtualFile[] {
105	        return Array.from(this.files.values());
106	    }
107	
108	    /**
109	     * Get file metadata
110	     */
111	    getFileInfo(path: string): VirtualFile | undefined {
112	        return this.files.get(this.normalizePath(path));
113	    }
114	
115	    /**
116	     * Clear all files from the filesystem
117	     */
118	    clear(): void {
119	        this.files.clear();
120	    }
121	
122	    /**
123	     * Get the number of files in the filesystem
124	     */
125	    get size(): number {
126	        return this.files.size;
127	    }
128	
129	    /**
130	     * Normalize a file path
131	     */
132	    private normalizePath(path: string): string {
133	        // Remove vfs:// protocol if present
134	        let normalized = path.replace(/^vfs:\/\//, '');
135	
136	        // Ensure path starts with /
137	        if (!normalized.startsWith('/')) {
138	            normalized = '/' + normalized;
139	        }
140	
141	        // Remove trailing slashes except for root
142	        if (normalized.length > 1 && normalized.endsWith('/')) {
143	            normalized = normalized.slice(0, -1);
144	        }
145	
146	        // Resolve . and .. segments
147	        const segments = normalized.split('/').filter(s => s.length > 0);
148	        const resolved: string[] = [];
149	
150	        for (const segment of segments) {
151	            if (segment === '.') {
152	                continue;
153	            } else if (segment === '..') {
154	                if (resolved.length > 0) {
155	                    resolved.pop();
156	                }
157	            } else {
158	                resolved.push(segment);
159	            }
160	        }
