320	            contextValues: execState.contextState || {},
321	            turnState: execState.turnState,
322	            paths: execState.paths,           // Save full paths array
323	            barriers: execState.barriers       // Save barrier state
324	        },
325	        status: getExecutionStatus(execState),
326	        lastUpdated: new Date().toISOString()
327	    };
328	
329	    await saveExecutionState(executionId, state);
330	
331	    // Save machine snapshot (in case it was modified by meta-tools)
332	    await saveMachineSnapshot(executionId, machineData);
333	
334	    // Update metadata
335	    metadata.lastExecutedAt = new Date().toISOString();
336	    metadata.status = state.status;
337	    metadata.stepCount = activePath?.stepCount || 0;
338	    if (executor.isInTurn()) {
339	        metadata.turnCount = executor.getTurnState()?.turnCount || metadata.turnCount;
340	    }
341	
342	    await saveExecutionMetadata(executionId, metadata);
343	
344	    logger.success(chalk.gray('💾 State saved'));
345	}
