34	/**
35	 * Execution metadata
36	 */
37	export interface ExecutionMetadata {
38	    id: string;                           // Execution ID
39	    machineFile?: string;                 // Original machine file path (if from file)
40	    machineSource: 'file' | 'stdin';      // Source type
41	    startedAt: string;                    // ISO timestamp
42	    lastExecutedAt: string;               // ISO timestamp
43	    turnCount: number;                    // Total turns executed
44	    stepCount: number;                    // Total steps executed
45	    status: 'in_progress' | 'complete' | 'error' | 'paused';
46	    mode: 'interactive' | 'playback' | 'auto';
47	    nextPathId?: string;                  // For --step-path mode: next path to step (round-robin)
48	    clientConfig?: {                      // Client configuration
49	        type: 'playback' | 'interactive' | 'api';
50	        recordingsDir?: string;
51	        playbackDir?: string;
