95	/**
96	 * Get the base state directory path
97	 */
98	export function getStateBaseDir(): string {
99	    return path.join(process.cwd(), STATE_CONFIG.baseDir, STATE_CONFIG.executionsDir);
100	}
101	
102	/**
103	 * Get execution directory path
104	 */
105	export function getExecutionDir(executionId: string): string {
106	    return path.join(getStateBaseDir(), executionId);
107	}
108	
109	/**
110	 * Generate a unique execution ID
111	 */
112	export function generateExecutionId(): string {
113	    const timestamp = new Date().toISOString()
114	        .replace(/[-:]/g, '')
115	        .replace(/\.\d+Z$/, '')
116	        .replace('T', '-');
117	    return `exec-${timestamp}`;
118	}
