120	/**
121	 * Generate hash of machine definition for validation
122	 */
123	export function hashMachine(machineData: MachineJSON): string {
124	    const json = JSON.stringify(machineData, Object.keys(machineData).sort());
125	    return crypto.createHash('sha256').update(json).digest('hex');
126	}
