289	/**
290	 * List all executions
291	 */
292	export async function listExecutions(): Promise<ExecutionMetadata[]> {
293	    const baseDir = getStateBaseDir();
294	
295	    try {
296	        const entries = await fs.readdir(baseDir);
297	        const executions: ExecutionMetadata[] = [];
298	
299	        for (const entry of entries) {
300	            if (entry === STATE_CONFIG.lastSymlink) continue;
301	
302	            try {
303	                const metadata = await loadExecutionMetadata(entry);
304	                executions.push(metadata);
305	            } catch {
306	                // Skip invalid executions
307	            }
308	        }
309	
310	        // Sort by last executed time (most recent first)
311	        executions.sort((a, b) =>
312	            new Date(b.lastExecutedAt).getTime() - new Date(a.lastExecutedAt).getTime()
313	        );
314	
315	        return executions;
316	    } catch {
317	        return [];
318	    }
319	}
