321	/**
322	 * Remove execution
323	 */
324	export async function removeExecution(executionId: string): Promise<void> {
325	    const execDir = getExecutionDir(executionId);
326	
327	    // Check if this is the "last" execution
328	    const lastId = await getLastExecutionId();
329	    if (lastId === executionId) {
330	        // Remove last symlink
331	        const baseDir = getStateBaseDir();
332	        const lastLink = path.join(baseDir, STATE_CONFIG.lastSymlink);
333	        try {
334	            await fs.unlink(lastLink);
335	        } catch {
336	            // Already removed
337	        }
338	    }
339	
340	    // Remove execution directory
341	    await fs.rm(execDir, { recursive: true, force: true });
342	}
343	
344	/**
345	 * Result of cleaning executions
346	 */
347	export interface CleanExecutionsResult {
348	    cleaned: number;    // Successfully removed
349	    pending: number;    // In progress or paused (not cleaned when --all not provided)
350	    error: number;      // With error status (not cleaned when --all not provided)
351	    failed: number;     // Failed to remove
352	}
353	
354	/**
355	 * Clean completed executions
356	 */
357	export async function cleanCompletedExecutions(options: { all?: boolean } = {}): Promise<CleanExecutionsResult> {
358	    const executions = await listExecutions();
359	    const result: CleanExecutionsResult = {
360	        cleaned: 0,
361	        pending: 0,
362	        error: 0,
363	        failed: 0
364	    };
365	
366	    for (const execution of executions) {
367	        if (options.all || execution.status === 'complete') {
368	            try {
369	                await removeExecution(execution.id);
370	                result.cleaned++;
371	            } catch {
372	                // Failed to remove
373	                result.failed++;
374	            }
375	        } else {
376	            // Not cleaned - categorize by status
377	            if (execution.status === 'error') {
378	                result.error++;
379	            } else {
380	                // in_progress or paused
381	                result.pending++;
382	            }
383	        }
384	    }
385	
386	    return result;
387	}
