23	export class ToolRegistry {
24	    private staticTools = new Map<string, ToolDefinition>();
25	    private dynamicHandlers = new Map<string | RegExp, ToolHandler>();
26	
27	    /**
28	     * Register a static tool with fixed definition
29	     * @param tool The tool definition
30	     * @param handler The function to execute the tool
31	     */
32	    registerStatic(tool: ToolDefinition, handler: ToolHandler): void {
33	        this.staticTools.set(tool.name, tool);
34	        this.dynamicHandlers.set(tool.name, handler);
35	    }
36	
37	    /**
38	     * Register a dynamic tool handler (e.g., for transition_to_* pattern)
39	     * @param pattern String prefix or RegExp to match tool names
40	     * @param handler The function to execute matching tools
41	     */
42	    registerDynamic(pattern: string | RegExp, handler: ToolHandler): void {
43	        this.dynamicHandlers.set(pattern, handler);
44	    }
45	
46	    /**
47	     * Unregister a tool or pattern
48	     * @param nameOrPattern Tool name or pattern to unregister
49	     */
50	    unregister(nameOrPattern: string | RegExp): void {
51	        this.staticTools.delete(nameOrPattern as string);
52	        this.dynamicHandlers.delete(nameOrPattern);
53	    }
54	
55	    /**
56	     * Execute a tool by name
57	     * @param name The tool name
58	     * @param input The tool input
59	     * @returns The tool execution result
60	     * @throws Error if tool not found or execution fails
61	     */
62	    async executeTool(name: string, input: any): Promise<any> {
63	        // Check static tools first
64	        if (this.staticTools.has(name)) {
65	            const handler = this.dynamicHandlers.get(name);
66	            if (!handler) {
67	                throw new Error(`Handler not found for tool: ${name}`);
68	            }
69	            return await handler(name, input);
70	        }
71	
72	        // Check dynamic patterns
73	        for (const [pattern, handler] of this.dynamicHandlers) {
74	            if (this.matches(name, pattern)) {
75	                return await handler(name, input);
76	            }
77	        }
78	
79	        throw new Error(`Tool not found: ${name}`);
80	    }

