70	                logger.warn(`Warning: Ignoring invalid format '${f}'. Valid formats are: ${VALID_FORMATS.join(', ')}`);
71	            }
72	            return valid;
73	        });
74	
75	    return formats.length > 0 ? formats : ['json'];
76	}
