89	async function generateWithImports(fileName: string, opts: GenerateOptions, formats: GenerateFormat[]): Promise<void> {
90	    const services = createMachineServices(NodeFileSystem).Machine;
91	    const resolver = new FileSystemResolver();
92	    const workspace = new WorkspaceManager(services.shared.workspace.LangiumDocuments, resolver);
93	
94	    try {
95	        const fileUri = pathToFileURL(path.resolve(fileName)).toString();
96	
97	        // Link all imports
98	        logger.debug('Resolving imports...');
99	        await workspace.linkAll(fileUri);
100	
101	        const fileCount = workspace.documents.size;
102	        logger.debug(`Loaded ${fileCount} file(s) (including imports)`);
103	
104	        // Get entry document
105	        const entryDoc = workspace.documents.get(fileUri);
106	        if (!entryDoc) {
107	            logger.error(`Failed to load entry file: ${fileName}`);
108	            process.exit(1);
109	        }
110	
111	        // Generate using multi-file generator
112	        const generator = new MultiFileGenerator();
113	        const mergedMachine = await generator.generate(entryDoc, workspace);
114	
115	        const results: string[] = [];
116	
117	        // Generate each requested format
118	        for (const format of formats) {
119	            try {
120	                let res: FileGenerationResult | undefined;
121	                switch (format) {
122	                    case 'json':
123	                        res = generateJSON(mergedMachine, fileName, opts.destination);
124	                        break;
125	                    case 'graphviz':
126	                    case 'dot':
127	                        res = generateGraphviz(mergedMachine, fileName, opts.destination);
128	                        break;
129	                    case 'html':
130	                        res = generateHTML(mergedMachine, fileName, opts.destination);
131	                        break;
132	                    default:
133	                        logger.warn(`Format '${format}' is not supported for multi-file input`);
134	                        continue;
135	                }
136	                if (res) {
137	                    if (opts.destination) {
138	                        results.push(`Generated ${format.toUpperCase()}: ${res.filePath}`);
139	                        logger.debug(`Wrote ${format} to ${res.filePath}`);
140	                    } else {
141	                        logger.output(res.content);
142	                    }
143	                }
144	            } catch (error) {
145	                const errorMsg = `Failed to generate ${format.toUpperCase()}: ${error instanceof Error ? error.message : String(error)}`;
146	                results.push(errorMsg);
147	                logger.error(errorMsg);
148	            }
149	        }
150	
151	        if (opts.destination && results.length > 0) {
152	            logger.heading('\n✓ Generation Complete');
153	            results.forEach(result => logger.success('  ' + result));
154	
155	            if (formats.includes('html')) {
156	                logger.tip('\n💡 Tip: Open the HTML file in a browser to view the interactive diagram');
157	            }
158	        }
